Hmmm, I guess you modify just one line to decide how many it makes. Like I changed maxBattleMembers to a number (currently 3). Put this as plugin. If you want just one dude after the main character, change 3 to 2.
Game_Followers.prototype.setup = function() {
this._data = [];
for (let i = 1; i < 3; i++) {
this._data.push(new Game_Follower(i));
}
};

