This will absolutely work. Alternatively, one could do this approach:
Code:
(function() {

const_GameFollower_isVisible = Game_Follower.prototype.isVisible;
Game_Follower.prototype.isVisible = function() {

    if (this.actor() && this.actor().index() >= 2) {
      return false;
    }

    // feel free to add any other rule here

    // no custom rule applies, resume original code
    return _GameFollower_isVisible.call(this);
}

})();

